211	function getCsrfToken() {
212	    return document.querySelector('[name=csrfmiddlewaretoken]')?.value ||
213	        document.cookie.split('; ')
214	            .find(row => row.startsWith('csrftoken='))
215	            ?.split('=')[1];
216	}
217	
218	function getCanonicalPostUrl(sharePath) {
219	    return new URL(sharePath, window.location.origin).toString();
220	}
221	
222	async function sharePost(sharePath) {
223	    const url = getCanonicalPostUrl(sharePath);
224	    const shareData = {
225	        title: 'Family Feed',
226	        text: 'Check out this post from the family feed',
227	        url: url,
228	    };
229	
230	    try {
231	        if (navigator.share) {
232	            await navigator.share(shareData);
233	            return;
234	        }
235	    } catch (err) {
236	        if (err?.name !== 'AbortError') {
237	            console.warn('Web Share failed, falling back to clipboard:', err);
238	        } else {
239	            return;
240	        }
241	    }
242	
243	    try {
244	        if (navigator.clipboard?.writeText) {
245	            await navigator.clipboard.writeText(url);
246	            alert('Link copied to clipboard');
247	            return;
248	        }
249	    } catch (err) {
250	        console.warn('Clipboard copy failed:', err);
251	    }
252	
253	    window.prompt('Copy this link', url);
254	}
255	
256	async function editPost(postId, currentContent) {
257	    const updatedContent = prompt('Edit your post', currentContent || '');
258	    if (updatedContent === null) {
259	        return;
260	    }
261	
262	    try {
263	        const response = await fetch(`/api/famstream/${postId}/`, {
264	            method: 'PATCH',
265	            headers: {
266	                'Content-Type': 'application/json',
267	                'X-CSRFToken': getCsrfToken()
268	            },
269	            body: JSON.stringify({ content: updatedContent })
270	        });
271	
272	        if (response.ok) {
273	            location.reload();
274	            return;
275	        }
276	
277	        const payload = await response.json().catch(() => ({}));
278	        alert(payload.content?.[0] || payload.detail || 'Failed to update post');
279	    } catch (err) {
280	        console.error('Failed to edit post:', err);
281	        alert('Failed to update post. Please try again.');
282	    }
283	}
284	
285	async function togglePin(postId, isPinned) {
286	    try {
287	        const response = await fetch(`/api/famstream/${postId}/pin/`, {
288	            method: isPinned ? 'DELETE' : 'POST',
289	            headers: {
290	                'X-CSRFToken': getCsrfToken()
291	            }
292	        });
293	
294	        if (response.ok) {
295	            location.reload();
296	            return;
297	        }
298	
299	        const payload = await response.json().catch(() => ({}));
300	        alert(payload.error || 'Failed to pin post');
301	    } catch (err) {
302	        console.error('Failed to pin post:', err);
303	        alert('Failed to pin post. Please try again.');
304	    }
305	}
306	
307	async function deletePost(postId) {
308	    if (!confirm('Delete this post? This cannot be undone.')) {
309	        return;
310	    }
311	
312	    try {
313	        const response = await fetch(`/api/famstream/${postId}/`, {
314	            method: 'DELETE',
315	            headers: {
316	                'X-CSRFToken': getCsrfToken()
317	            }
318	        });
319	
320	        if (response.ok) {
321	            location.reload();
322	            return;
323	        }
324	
325	        alert('Failed to delete post. Please try again.');
326	    } catch (err) {
327	        console.error('Failed to delete post:', err);
328	        alert('Failed to delete post. Please try again.');
329	    }
330	}
331	
332	async function addComment(event, postId) {
333	    event.preventDefault();
334	    const form = event.target;
335	    const content = form.content.value;
336	
337	    try {
338	        const response = await fetch(`/api/famstream/${postId}/comments/`, {
339	            method: 'POST',
340	            headers: {
341	                'Content-Type': 'application/json',
342	                'X-CSRFToken': form.querySelector('[name=csrfmiddlewaretoken]').value
343	            },
344	            body: JSON.stringify({ content: content })
345	        });
346	
347	        if (response.ok) {
348	            location.reload();
349	        }
350	    } catch (err) {
351	        console.error('Failed to add comment:', err);
352	    }
353	}
354	</script>
