    grid-template-columns: 1fr;
}

.media-grid.two {
    grid-template-columns: repeat(2, 1fr);
}

.media-grid.multi {
    grid-template-columns: repeat(2, 1fr);
}

.media-item {
    position: relative;
    overflow: hidden;
    background: var(--gray-100);
}

.media-item img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    cursor: pointer;
    transition: transform var(--transition-fast);
}

.media-item img:hover {
    transform: scale(1.02);
}

.media-item.single img {
    max-height: 500px;
}

.media-item:not(.single) img {
    height: 200px;
}

.media-more-overlay {
    position: absolute;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--white);
    font-size: var(--font-size-2xl);
