<article class="post-card" data-post-id="{{ post.id }}">
    <!-- Post Header -->
    <header class="post-header">
        <div class="post-avatar">
            {% if post.author.socialaccount_set.all.0.get_avatar_url %}
                <img src="{{ post.author.socialaccount_set.all.0.get_avatar_url }}" alt="{{ post.author.get_full_name|default:post.author.username }}">
            {% else %}
                {{ post.author.first_name.0|default:post.author.username.0|upper }}
            {% endif %}
        </div>
        <div class="post-meta">
            <div class="post-author">{{ post.author.get_full_name|default:post.author.username }}</div>
            <div class="post-time">{{ post.created_at|timesince }} ago</div>
        </div>
        <div class="post-families">
            {% if post.is_pinned %}
                <span class="badge bg-warning text-dark">Pinned</span>
            {% endif %}
            {% if post.linked_recipe and post.linked_recipe.shared_meta_families.all %}
                {% for network in post.linked_recipe.shared_meta_families.all %}
                    <span class="badge bg-info">{{ network.name }}</span>
                {% endfor %}
            {% else %}
                {% for visibility in post.visibility.all %}
                    <span class="badge bg-info">{{ visibility.family.name }}</span>
                {% endfor %}
            {% endif %}
        </div>
    </header>

    <!-- Post Content -->
    {% if post.content %}
    <div class="post-content">
        <div class="post-text">{{ post.content }}</div>
    </div>
    {% endif %}

    <!-- Linked Content -->
    {% if post.linked_event %}
    <div class="linked-content">
        <div class="linked-content-header">
            <i class="bi bi-calendar-event"></i>
            <span>Event</span>
        </div>
        <div class="linked-content-title">
            <a href="{% url 'event_detail' post.linked_event.id %}">{{ post.linked_event.title }}</a>
        </div>
    </div>
    {% endif %}

    {% if post.linked_trip %}
    <div class="linked-content">
        <div class="linked-content-header">
            <i class="bi bi-umbrella-beach"></i>
            <span>Trip</span>
        </div>
        <div class="linked-content-title">
            <a href="{% url 'trips:trip_detail' post.linked_trip.id %}">{{ post.linked_trip.name }}</a>
        </div>
    </div>
    {% endif %}

    {% if post.linked_recipe %}
    <div class="linked-content">
        <div class="linked-content-header">
            <i class="bi bi-egg-fried"></i>
            <span>Recipe</span>
        </div>
        <div class="linked-content-title">
            {{ post.linked_recipe.title }}
        </div>
    </div>
    {% endif %}

    <!-- Media Gallery -->
    {% if post.media.all %}
    <div class="post-media">
        {% with media_list=post.media.all %}
        {% with media_count=media_list|length %}
        <div class="media-grid {% if media_count == 1 %}single{% elif media_count == 2 %}two{% else %}multi{% endif %}">
            {% for media in media_list|slice:":4" %}
                <div class="media-item {% if media_count == 1 %}single{% endif %}">
                    {% if media.media_type == 'IMAGE' %}
                        <img src="{{ media.file_url }}" alt="Post media" loading="lazy">
                    {% else %}
                        <video controls{% if media.thumbnail_url %} poster="{{ media.thumbnail_url }}"{% endif %} preload="metadata">
                            <source src="{{ media.file_url }}" type="{{ media.content_type }}">
                        </video>
                    {% endif %}
                    {% if forloop.counter == 4 and media_count > 4 %}
                        <div class="media-more-overlay">+{{ media_count|add:"-4" }}</div>
                    {% endif %}
                </div>
            {% endfor %}
        </div>
        {% endwith %}
        {% endwith %}
    </div>
    {% endif %}

    <!-- Reactions Summary -->
    {% if post.reactions.all %}
    <div class="post-reactions">
        {% regroup post.reactions.all by emoji as emoji_groups %}
        {% for emoji_group in emoji_groups %}
            <span class="reaction-badge {% if request.user in emoji_group.list|map:'user' %}user-reacted{% endif %}">
                {{ emoji_group.grouper }} {{ emoji_group.list|length }}
            </span>
        {% endfor %}
        <span class="text-muted ms-auto" style="font-size: var(--font-size-sm);">
            {{ post.view_count }} view{{ post.view_count|pluralize }}
        </span>
    </div>
    {% endif %}

    <!-- Post Actions -->
    <div class="post-actions">
        <div class="reaction-picker">
            <button class="post-action-btn" type="button">
                <i class="bi bi-emoji-smile"></i>
                React
            </button>
            <div class="reaction-picker-dropdown">
                {% for emoji, name in available_emojis %}
                    <button class="reaction-picker-btn" data-post-id="{{ post.id }}" data-emoji="{{ emoji }}" title="{{ name }}">
                        {{ emoji }}
                    </button>
                {% endfor %}
            </div>
        </div>

        <button class="post-action-btn" type="button" onclick="toggleComments('{{ post.id }}')">
            <i class="bi bi-chat"></i>
            {{ post.comment_count }} Comment{{ post.comment_count|pluralize }}
        </button>

        <button class="post-action-btn" type="button" data-share-path="{% url 'famstream:feed' %}?post={{ post.id }}" onclick="sharePost(this.dataset.sharePath)">
            <i class="bi bi-share"></i>
            Share
        </button>
    </div>

    {% if request.user == post.author %}
    <div class="px-4 pb-3">
        <div class="d-flex gap-2 flex-wrap">
            <button class="btn btn-outline-secondary btn-sm flex-fill" type="button"
                    data-post-control="pin"
                    onclick="togglePin('{{ post.id }}', {{ post.is_pinned|yesno:'true,false' }})">
                <i class="bi bi-star{% if post.is_pinned %}-fill{% endif %} me-1"></i>{% if post.is_pinned %}Unpin post{% else %}Pin post{% endif %}
            </button>
            <button class="btn btn-outline-secondary btn-sm flex-fill" type="button"
                    data-post-control="edit"
                    onclick="editPost('{{ post.id }}', '{{ post.content|escapejs }}')">
                <i class="bi bi-pencil me-1"></i>Edit post
            </button>
            <button class="btn btn-outline-danger btn-sm flex-fill" type="button"
                    data-post-control="delete"
                    onclick="deletePost('{{ post.id }}')">
                <i class="bi bi-trash me-1"></i>Delete post
            </button>
        </div>
    </div>
    {% endif %}

    <!-- Comments Section -->
    <div class="post-comments" id="comments-{{ post.id }}" style="display: none;">
        {% with comments=post.comments.all|slice:":3" %}
            {% if post.comment_count > 3 %}
                <div class="view-all-comments">
                    View all {{ post.comment_count }} comments
                </div>
            {% endif %}

            {% for comment in comments %}
                <div class="comment-item">
                    <div class="comment-avatar">
                        {{ comment.author.first_name.0|default:comment.author.username.0|upper }}
                    </div>
                    <div class="comment-content">
                        <div class="comment-author">{{ comment.author.get_full_name|default:comment.author.username }}</div>
                        <div class="comment-text">{{ comment.content }}</div>
                        <div class="comment-time">{{ comment.created_at|timesince }} ago</div>
                    </div>
                </div>
            {% empty %}
                <p class="text-muted text-center mb-0">No comments yet. Be the first to comment!</p>
            {% endfor %}
        {% endwith %}

        <!-- Add Comment Form -->
        <form class="mt-3" onsubmit="addComment(event, '{{ post.id }}')">
            {% csrf_token %}
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Write a comment..." name="content" required>
                <button class="btn btn-primary" type="submit">
                    <i class="bi bi-send"></i>
                </button>
            </div>
        </form>
    </div>
</article>

<script>
function toggleComments(postId) {
    const comments = document.getElementById('comments-' + postId);
    comments.style.display = comments.style.display === 'none' ? 'block' : 'none';
}

function getCsrfToken() {
    return document.querySelector('[name=csrfmiddlewaretoken]')?.value ||
        document.cookie.split('; ')
            .find(row => row.startsWith('csrftoken='))
            ?.split('=')[1];
}

function getCanonicalPostUrl(sharePath) {
    return new URL(sharePath, window.location.origin).toString();
}

async function sharePost(sharePath) {
    const url = getCanonicalPostUrl(sharePath);
    const shareData = {
        title: 'Family Feed',
        text: 'Check out this post from the family feed',
        url: url,
    };

    try {
        if (navigator.share) {
            await navigator.share(shareData);
            return;
        }
    } catch (err) {
        if (err?.name !== 'AbortError') {
            console.warn('Web Share failed, falling back to clipboard:', err);
        } else {
            return;
        }
    }

    try {
        if (navigator.clipboard?.writeText) {
            await navigator.clipboard.writeText(url);
            alert('Link copied to clipboard');
            return;
        }
    } catch (err) {
        console.warn('Clipboard copy failed:', err);
    }

    window.prompt('Copy this link', url);
}

async function editPost(postId, currentContent) {
    const updatedContent = prompt('Edit your post', currentContent || '');
    if (updatedContent === null) {
        return;
    }

    try {
        const response = await fetch(`/api/famstream/${postId}/`, {
            method: 'PATCH',
            headers: {
                'Content-Type': 'application/json',
                'X-CSRFToken': getCsrfToken()
            },
            body: JSON.stringify({ content: updatedContent })
        });

        if (response.ok) {
            location.reload();
            return;
        }

        const payload = await response.json().catch(() => ({}));
        alert(payload.content?.[0] || payload.detail || 'Failed to update post');
    } catch (err) {
        console.error('Failed to edit post:', err);
        alert('Failed to update post. Please try again.');
    }
}

async function togglePin(postId, isPinned) {
    try {
        const response = await fetch(`/api/famstream/${postId}/pin/`, {
            method: isPinned ? 'DELETE' : 'POST',
            headers: {
                'X-CSRFToken': getCsrfToken()
            }
        });

        if (response.ok) {
            location.reload();
            return;
        }

        const payload = await response.json().catch(() => ({}));
        alert(payload.error || 'Failed to pin post');
    } catch (err) {
        console.error('Failed to pin post:', err);
        alert('Failed to pin post. Please try again.');
    }
}

async function deletePost(postId) {
    if (!confirm('Delete this post? This cannot be undone.')) {
        return;
    }

    try {
        const response = await fetch(`/api/famstream/${postId}/`, {
            method: 'DELETE',
            headers: {
                'X-CSRFToken': getCsrfToken()
            }
        });

        if (response.ok) {
            location.reload();
            return;
        }

        alert('Failed to delete post. Please try again.');
    } catch (err) {
        console.error('Failed to delete post:', err);
        alert('Failed to delete post. Please try again.');
    }
}

async function addComment(event, postId) {
    event.preventDefault();
    const form = event.target;
    const content = form.content.value;

    try {
        const response = await fetch(`/api/famstream/${postId}/comments/`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-CSRFToken': form.querySelector('[name=csrfmiddlewaretoken]').value
            },
            body: JSON.stringify({ content: content })
        });

        if (response.ok) {
            location.reload();
        }
    } catch (err) {
        console.error('Failed to add comment:', err);
    }
}
</script>
