{% block content %}
<div class="container">
    <div class="d-flex justify-content-between align-items-center mb-4">
        <h1><i class="bi bi-newspaper me-2" style="color: var(--section-feed, #EC4899);"></i>Family Feed</h1>
        <button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#createPostModal">
            <i class="bi bi-plus-lg me-2"></i>Create Post
        </button>
    </div>

    <div class="feed-container">
        <!-- Filter Sidebar -->
        <aside class="filter-sidebar">
            <div class="filter-header">
                <h5><i class="bi bi-funnel me-2"></i>Filters</h5>
            </div>

            <form method="get" action="{% url 'famstream:feed' %}">
                <div class="filter-group">
                    <label for="family">Family</label>
                    <select class="form-select" id="family" name="family" onchange="this.form.submit()">
                        <option value="">All Families</option>
                        {% for family in user_families %}
                            <option value="{{ family.id }}" {% if selected_family.id == family.id %}selected{% endif %}>
                                {{ family.name }}
                            </option>
                        {% endfor %}
                    </select>
                </div>

                {% if selected_family %}
                <div class="mt-3">
                    <a href="{% url 'famstream:feed' %}" class="btn btn-outline-secondary btn-sm w-100">
                        <i class="bi bi-x me-1"></i>Clear Filter
                    </a>
                </div>
                {% endif %}
            </form>

            <!-- Quick Stats -->
            <div class="mt-4 pt-4 border-top">
                <h6 class="text-muted mb-3">Your Families</h6>
                <div class="d-flex flex-wrap gap-2">
                    {% for family in user_families %}
                        <span class="badge bg-primary-light text-primary">{{ family.name }}</span>
                    {% endfor %}
                </div>
            </div>
        </aside>

        <!-- Main Feed -->
        <div class="feed-main-content">
            {% if posts %}
                {% for post in posts %}
                    {% include "famstream/partials/_post_card.html" with post=post %}
                {% endfor %}

                <!-- Pagination -->
                {% if page_obj.has_other_pages %}
                <nav aria-label="Feed pagination" class="mt-4">
                    <ul class="pagination justify-content-center">
                        {% if page_obj.has_previous %}
                            <li class="page-item">
                                <a class="page-link" href="?page={{ page_obj.previous_page_number }}{% if selected_family %}&family={{ selected_family.id }}{% endif %}">
                                    <i class="bi bi-chevron-left"></i>
                                </a>
                            </li>
                        {% endif %}

                        <li class="page-item disabled">
                            <span class="page-link">Page {{ page_obj.number }} of {{ page_obj.paginator.num_pages }}</span>
                        </li>

                        {% if page_obj.has_next %}
                            <li class="page-item">
                                <a class="page-link" href="?page={{ page_obj.next_page_number }}{% if selected_family %}&family={{ selected_family.id }}{% endif %}">
                                    <i class="bi bi-chevron-right"></i>
                                </a>
                            </li>
                        {% endif %}
                    </ul>
                </nav>
                {% endif %}
            {% else %}
                <div class="empty-state">
                    <i class="bi bi-newspaper"></i>
                    <h3>No posts yet</h3>
                    <p>Be the first to share something with your family!</p>
                    <button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#createPostModal">
                        <i class="bi bi-plus-lg me-2"></i>Create Post
                    </button>
                </div>
            {% endif %}
        </div>
    </div>
</div>

<!-- Create Post Modal -->
{% include "famstream/partials/_create_post_modal.html" %}
{% endblock %}

{% block extra_js %}
<script>
document.addEventListener('DOMContentLoaded', function() {
    // Scroll to and highlight a post if linked from a notification
    {% if highlight_post_id %}
    (function() {
        var target = document.querySelector('[data-post-id="{{ highlight_post_id|escapejs }}"]');
        if (target) {
            target.scrollIntoView({ behavior: 'smooth', block: 'center' });
            target.style.outline = '3px solid var(--section-feed, #EC4899)';
            target.style.outlineOffset = '4px';
            target.style.borderRadius = 'var(--radius-lg)';
            setTimeout(function() {
                target.style.transition = 'outline-color 1s ease';
                target.style.outlineColor = 'transparent';
            }, 3000);
        }
    })();
    {% endif %}

    // Initialize reaction pickers
    document.querySelectorAll('.reaction-picker').forEach(picker => {
        const btn = picker.querySelector('.post-action-btn');
        const dropdown = picker.querySelector('.reaction-picker-dropdown');

        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            dropdown.classList.toggle('show');
        });
    });

    // Close dropdowns on outside click
    document.addEventListener('click', () => {
        document.querySelectorAll('.reaction-picker-dropdown.show').forEach(d => {
            d.classList.remove('show');
        });
    });

    // Handle reaction clicks
    document.querySelectorAll('.reaction-picker-btn').forEach(btn => {
        btn.addEventListener('click', async (e) => {
            e.stopPropagation();
            const postId = btn.dataset.postId;
            const emoji = btn.dataset.emoji;

            try {
                const response = await fetch(`/api/famstream/${postId}/reactions/`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'X-CSRFToken': getCsrfToken()
                    },
                    body: JSON.stringify({ emoji: emoji })
                });

                if (response.ok) {
                    location.reload();
                }
            } catch (err) {
                console.error('Failed to add reaction:', err);
            }
        });
    });

    function getCsrfToken() {
        return document.querySelector('[name=csrfmiddlewaretoken]')?.value ||
               document.cookie.split('; ')
                   .find(row => row.startsWith('csrftoken='))
                   ?.split('=')[1];
    }
});
