// Lightbox
var _lbPostId = null;
var _lbIndex = 0;

function openLightbox(postId, index) {
    var items = (window._postMedia || {})[postId];
    if (!items || !items.length) return;
    _lbPostId = postId;
    _lbIndex = index;
    renderLightbox();
    document.getElementById('mediaLightbox').hidden = false;
    document.body.style.overflow = 'hidden';
}

function closeLightbox() {
    document.getElementById('mediaLightbox').hidden = true;
    document.body.style.overflow = '';
    var container = document.getElementById('lightboxContent');
    var video = container.querySelector('video');
    if (video) video.pause();
    _lbPostId = null;
}

function navigateLightbox(dir) {
    var items = (window._postMedia || {})[_lbPostId];
    if (!items) return;
    var video = document.getElementById('lightboxContent').querySelector('video');
    if (video) video.pause();
    _lbIndex = (_lbIndex + dir + items.length) % items.length;
    renderLightbox();
}

function renderLightbox() {
    var items = (window._postMedia || {})[_lbPostId];
    if (!items) return;
    var item = items[_lbIndex];
    var container = document.getElementById('lightboxContent');
    if (item.type === 'IMAGE') {
        container.innerHTML = '<img src="' + item.url + '" alt="Media">';
    } else {
        var poster = item.thumbnail ? ' poster="' + item.thumbnail + '"' : '';
        container.innerHTML = '<video controls autoplay' + poster + '><source src="' + item.url + '" type="' + item.contentType + '"></video>';
    }
    var counter = document.getElementById('lightboxCounter');
    counter.textContent = (_lbIndex + 1) + ' / ' + items.length;
    document.querySelector('.lightbox-prev').style.display = items.length > 1 ? '' : 'none';
    document.querySelector('.lightbox-next').style.display = items.length > 1 ? '' : 'none';
}

document.getElementById('mediaLightbox').addEventListener('click', function(e) {
    if (e.target === this) closeLightbox();
});

document.addEventListener('keydown', function(e) {
    if (document.getElementById('mediaLightbox').hidden) return;
    if (e.key === 'Escape') closeLightbox();
    else if (e.key === 'ArrowLeft') navigateLightbox(-1);
    else if (e.key === 'ArrowRight') navigateLightbox(1);
});
</script>
