<style>
    /* Feed Layout */
    .feed-container {
        display: flex;
        gap: var(--space-4);
        margin-top: var(--space-4);
    }

    .filter-sidebar {
        flex: 0 0 280px;
        background: var(--white);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow);
        padding: var(--space-4);
        height: fit-content;
        position: sticky;
        top: 80px;
        border-top: 3px solid var(--section-feed, #EC4899);
    }

    .feed-main-content {
        flex: 1;
        min-width: 0;
        max-width: 680px;
    }

    .filter-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: var(--space-4);
        padding-bottom: var(--space-3);
        border-bottom: 1px solid var(--gray-200);
    }

    .filter-header h5 {
        margin: 0;
        font-size: var(--font-size-lg);
        font-weight: 600;
        color: var(--gray-900);
    }

    .filter-group {
        margin-bottom: var(--space-4);
    }

    .filter-group label {
        display: block;
        margin-bottom: var(--space-2);
        font-weight: 500;
        color: var(--gray-700);
        font-size: var(--font-size-sm);
    }

    /* Post Card Styles */
    .post-card {
        background-color: var(--white);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow);
        margin-bottom: var(--space-4);
        overflow: hidden;
    }

    .post-header {
        display: flex;
        align-items: center;
        padding: var(--space-4);
        border-bottom: 1px solid var(--gray-100);
    }

    .post-avatar {
        width: 48px;
        height: 48px;
        border-radius: var(--radius-full);
        background: #FCE7F3;
        display: flex;
        align-items: center;
        justify-content: center;
        color: var(--section-feed, #EC4899);
        font-weight: 600;
        font-size: var(--font-size-lg);
        margin-right: var(--space-3);
    }

    .post-avatar img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        border-radius: var(--radius-full);
    }

    .post-meta {
        flex: 1;
    }

    .post-author {
        font-weight: 600;
        color: var(--gray-900);
        margin-bottom: 2px;
    }

    .post-time {
        font-size: var(--font-size-sm);
        color: var(--gray-500);
    }

    .post-families {
        display: flex;
        gap: var(--space-1);
        flex-wrap: wrap;
    }

    .post-families .badge {
        font-size: var(--font-size-xs);
        font-weight: 500;
    }

    .post-content {
        padding: var(--space-4);
    }

    .post-text {
        font-size: var(--font-size-base);
        color: var(--gray-800);
        line-height: 1.6;
        white-space: pre-wrap;
    }

    /* Media Gallery */
    .post-media {
        padding: 0 var(--space-4) var(--space-4);
    }

    .media-grid {
        display: grid;
        gap: var(--space-2);
        border-radius: var(--radius-md);
        overflow: hidden;
    }

    .media-grid.single {
        grid-template-columns: 1fr;
    }

    .media-grid.two {
        grid-template-columns: repeat(2, 1fr);
    }

    .media-grid.multi {
        grid-template-columns: repeat(2, 1fr);
    }

    .media-item {
        position: relative;
        overflow: hidden;
        background: var(--gray-100);
    }

    .media-item img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        cursor: pointer;
        transition: transform var(--transition-fast);
    }

    .media-item img:hover {
        transform: scale(1.02);
    }

    .media-item.single img {
        max-height: 500px;
    }

    .media-item:not(.single) img {
        height: 200px;
    }

    .media-more-overlay {
        position: absolute;
        inset: 0;
        background: rgba(0, 0, 0, 0.5);
        display: flex;
        align-items: center;
        justify-content: center;
        color: var(--white);
        font-size: var(--font-size-2xl);
        font-weight: 600;
        cursor: pointer;
    }

    /* Lightbox */
    .lightbox-backdrop {
        position: fixed;
        inset: 0;
        z-index: 9999;
        background: rgba(0, 0, 0, 0.92);
        display: flex;
        align-items: center;
        justify-content: center;
    }

    .lightbox-backdrop[hidden] {
        display: none;
    }

    .lightbox-content {
        position: relative;
        max-width: 90vw;
        max-height: 90vh;
        display: flex;
        align-items: center;
        justify-content: center;
    }

    .lightbox-content img {
        max-width: 90vw;
        max-height: 85vh;
        object-fit: contain;
        border-radius: var(--radius-md);
    }

    .lightbox-content video {
        max-width: 90vw;
        max-height: 85vh;
        border-radius: var(--radius-md);
    }

    .lightbox-close {
        position: fixed;
        top: var(--space-4);
        right: var(--space-4);
        background: none;
        border: none;
        color: var(--white);
        font-size: 2rem;
        cursor: pointer;
        z-index: 10000;
        padding: var(--space-2);
        line-height: 1;
    }

    .lightbox-nav {
        position: fixed;
        top: 50%;
        transform: translateY(-50%);
        background: rgba(255, 255, 255, 0.15);
        border: none;
        color: var(--white);
        font-size: 1.5rem;
        cursor: pointer;
        z-index: 10000;
        padding: var(--space-3) var(--space-4);
        border-radius: var(--radius-md);
        transition: background var(--transition-fast);
    }

    .lightbox-nav:hover {
        background: rgba(255, 255, 255, 0.3);
    }

    .lightbox-prev { left: var(--space-4); }
    .lightbox-next { right: var(--space-4); }

    .lightbox-counter {
        position: fixed;
        bottom: var(--space-4);
        left: 50%;
        transform: translateX(-50%);
        color: var(--white);
        font-size: var(--font-size-sm);
        z-index: 10000;
    }

    /* Linked Content */
    .linked-content {
        margin: 0 var(--space-4) var(--space-4);
        padding: var(--space-3);
        background: var(--gray-50);
        border-radius: var(--radius-md);
        border: 1px solid var(--gray-200);
    }

    .linked-content-header {
        display: flex;
        align-items: center;
        gap: var(--space-2);
        font-size: var(--font-size-sm);
        color: var(--gray-500);
        margin-bottom: var(--space-2);
    }

    .linked-content-title {
        font-weight: 600;
        color: var(--gray-900);
    }

    .linked-content-title a {
        text-decoration: none;
        color: inherit;
    }

    .linked-content-title a:hover {
        color: var(--primary);
    }

    /* Reactions */
    .post-reactions {
        display: flex;
        align-items: center;
        padding: var(--space-2) var(--space-4);
        border-top: 1px solid var(--gray-100);
        gap: var(--space-2);
    }

    .reaction-badge {
        display: inline-flex;
        align-items: center;
        gap: var(--space-1);
        padding: 4px 8px;
        background: var(--gray-100);
        border-radius: var(--radius-full);
        font-size: var(--font-size-sm);
        color: var(--gray-700);
    }

    .reaction-badge.user-reacted {
        background: var(--primary-light);
        color: var(--primary);
    }

    /* Post Actions */
    .post-actions {
        display: flex;
        padding: var(--space-3) var(--space-4);
        border-top: 1px solid var(--gray-100);
        gap: var(--space-2);
    }

    .post-action-btn {
        flex: 1;
        display: flex;
        align-items: center;
        justify-content: center;
        gap: var(--space-2);
        padding: var(--space-2) var(--space-3);
        border: none;
        background: none;
        color: var(--gray-600);
        font-size: var(--font-size-sm);
        font-weight: 500;
        border-radius: var(--radius-md);
        cursor: pointer;
        transition: all var(--transition-fast);
    }

    .post-action-btn:hover {
        background: var(--gray-100);
        color: var(--gray-900);
    }

    .post-action-btn.active {
        color: var(--primary);
    }

    /* Comments Section */
    .post-comments {
        padding: var(--space-4);
        border-top: 1px solid var(--gray-100);
        background: var(--gray-50);
    }

    .comment-item {
        display: flex;
        gap: var(--space-3);
        margin-bottom: var(--space-3);
    }

    .comment-item:last-child {
        margin-bottom: 0;
    }

    .comment-avatar {
        width: 32px;
